// Construit la requête Anthropic (vision) à partir de l'image + du contexte
const ctx = $('Préparer le contexte').first().json;

const buffer = await this.helpers.getBinaryDataBuffer(0, 'image');
const b64 = buffer.toString('base64');
const mime = (items[0].binary && items[0].binary.image && items[0].binary.image.mimeType) || 'image/jpeg';

const systemPrompt = $vars.SYSTEM_PROMPT || `Tu es un assistant d'estimation pour artisans et prestataires de services. À partir d'une photo d'un chantier ou d'un besoin, tu produis une estimation de devis détaillée, réaliste et prudente.

Règles strictes :
1. Tu raisonnes d'abord sur ce que tu observes (surface, état, complexité, accès, matériaux) avant de chiffrer.
2. Tu estimes les quantités via des repères d'échelle (prise, porte ~2m, carrelage ~30cm). En cas de doute, fourchette basse.
3. Tu utilises la grille tarifaire fournie. À défaut, tarifs marché France et tu le signales.
4. Tu ne factures jamais un poste non justifiable par la photo ou le contexte.
5. Tu signales tout ce qui nécessite une visite physique.

Réponds UNIQUEMENT avec un objet JSON valide, sans texte ni balises Markdown, selon ce schéma :
{"resume_observation":string,"type_prestation":string,"hypotheses":[string],"lignes":[{"poste":string,"description":string,"quantite":number,"unite":string,"prix_unitaire_ht":number,"total_ht":number}],"total_ht":number,"tva_taux":number,"total_ttc":number,"niveau_confiance":"eleve|moyen|faible","points_a_confirmer":[string],"validite_jours":number}

Cohérence : total_ht = somme des lignes ; total_ttc = total_ht*(1+tva_taux). Euros, nombres sans symbole. Si la photo est inexploitable : lignes vides, niveau_confiance "faible", message dans points_a_confirmer.`;

const userText = [
  `Type d'activité : ${ctx.type_activite}`,
  `Contexte fourni par le client : ${ctx.contexte_client || 'aucun'}`,
  `Grille tarifaire de référence : ${ctx.grille_tarifaire || 'non fournie'}`,
  `Taux de TVA applicable : ${ctx.tva_taux}`
].join('\n');

const requestBody = {
  model: 'claude-sonnet-4-6',
  max_tokens: 2000,
  system: systemPrompt,
  messages: [{
    role: 'user',
    content: [
      { type: 'image', source: { type: 'base64', media_type: mime, data: b64 } },
      { type: 'text', text: userText }
    ]
  }]
};

return [{ json: { requestBody } }];

// Extrait le JSON de la réponse Claude et recalcule les totaux par sécurité
const resp = $json;
let text = '';
if (resp.content && Array.isArray(resp.content)) {
  text = resp.content.filter(b => b.type === 'text').map(b => b.text).join('\n');
}
text = text.trim().replace(/^```json\s*/i, '').replace(/^```\s*/i, '').replace(/```$/,'').trim();

let devis;
try {
  devis = JSON.parse(text);
} catch (e) {
  throw new Error('Réponse IA non parsable en JSON : ' + text.slice(0, 300));
}

let totalHT = 0;
(devis.lignes || []).forEach(l => {
  l.prix_unitaire_ht = Number(l.prix_unitaire_ht) || 0;
  l.quantite = Number(l.quantite) || 0;
  l.total_ht = Math.round(l.quantite * l.prix_unitaire_ht * 100) / 100;
  totalHT += l.total_ht;
});
const tva = (devis.tva_taux != null) ? Number(devis.tva_taux) : 0.20;
devis.total_ht = Math.round(totalHT * 100) / 100;
devis.tva_taux = tva;
devis.total_tva = Math.round(devis.total_ht * tva * 100) / 100;
devis.total_ttc = Math.round(devis.total_ht * (1 + tva) * 100) / 100;

const now = new Date();
const stamp = now.toISOString().slice(0,10).replace(/-/g,'');
devis.numero = 'DEV-' + stamp + '-' + Math.floor(1000 + Math.random() * 9000);
devis.date = now.toLocaleDateString('fr-FR');
devis.validite_jours = devis.validite_jours || 30;

const ctx = $('Préparer le contexte').first().json;
devis.entreprise = ctx.nom_entreprise || 'Votre Entreprise';
devis.client = ctx.nom_client || 'Client';
devis.email_client = ctx.email_client || '';

return [{ json: devis }];

// Génère le HTML imprimable du devis
