.obs{background:#f9fafb;border-left:3px solid #111827;padding:12px 16px;font-size:13px;margin-bottom:24px;color:#374151}
table{width:100%;border-collapse:collapse;margin-bottom:8px}
th{text-align:left;font-size:10px;text-transform:uppercase;letter-spacing:.5px;color:#9ca3af;border-bottom:2px solid #e5e7eb;padding:8px}
td{padding:12px 8px;border-bottom:1px solid #f3f4f6;font-size:13px;vertical-align:top}
.poste{font-weight:600}
.desc{color:#6b7280;font-size:12px;margin-top:2px}
.num{text-align:right;white-space:nowrap}
.totaux{margin-left:auto;width:280px;margin-top:12px;font-size:14px}
.totaux .row{display:flex;justify-content:space-between;padding:6px 8px}
.totaux .ttc{font-weight:800;font-size:18px;border-top:2px solid #111827;margin-top:4px;padding-top:10px}
.foot{margin-top:32px;font-size:11px;color:#9ca3af;border-top:1px solid #e5e7eb;padding-top:16px}
.badge{display:inline-block;font-size:11px;font-weight:700;color:#fff;padding:3px 10px;border-radius:99px}
.confirm{background:#fffbeb;border:1px solid #fde68a;border-radius:8px;padding:12px 16px;font-size:12px;margin:16px 0;color:#92400e}
