</div>
<div class="meta">
  <div><div class="label">Date</div>${d.date}</div>
  <div><div class="label">Client</div>${d.client}</div>
  <div><div class="label">Prestation</div>${d.type_prestation||''}</div>
  <div><div class="label">Validité</div>${d.validite_jours} jours</div>
  <div><div class="label">Confiance estim.</div><span class="badge" style="background:${confiance}">${(d.niveau_confiance||'').toUpperCase()}</span></div>
</div>
<div class="obs">📷 ${d.resume_observation||''}</div>
<table>
