  <div class="row ttc"><span>Total TTC</span><span>${eur(d.total_ttc)}</span></div>
</div>
${aConfirmer ? `<div class="confirm"><strong>⚠️ À confirmer lors de la visite</strong><ul>${aConfirmer}</ul></div>` : ''}
<div class="foot">Devis estimatif généré à partir d'analyse photo — à confirmer après visite. ${d.entreprise} · Document non contractuel sans signature.</div>
</body></html>`;

return [{ json: { ...d, html } }];

